   550  void Mac::StartOperation(Operation aOperation)
   551  {
   552      if (aOperation != kOperationIdle)
   553      {
   554          otLogDebgMac("Request to start operation \"%s\"", OperationToString(aOperation));
   555
   556  #if OPENTHREAD_CONFIG_STAY_AWAKE_BETWEEN_FRAGMENTS
   557          if (mDelayingSleep)
   558          {
   559              otLogDebgMac("Canceling sleep delay");
   560              mTimer.Stop();
   561              mDelayingSleep    = false;
   562              mShouldDelaySleep = false;
   563          }
   564  #endif
   565      }
   566
   567      switch (aOperation)
   568      {
   569      case kOperationIdle:
   570          break;
   571
   572      case kOperationActiveScan:
   573          mPendingActiveScan = true;
   574          break;
   575
   576      case kOperationEnergyScan:
   577          mPendingEnergyScan = true;
   578          break;
   579
   580      case kOperationTransmitBeacon:
   581          mPendingTransmitBeacon = true;
   582          break;
   583
   584      case kOperationTransmitData:
   585          mPendingTransmitData = true;
   586          break;
   587
   588      case kOperationWaitingForData:
   589          mPendingWaitingForData = true;
   590          break;
   591
   592      case kOperationTransmitOutOfBandFrame:
   593          mPendingTransmitOobFrame = true;
   594          break;
   595      }
   596
   597      if (mOperation == kOperationIdle)
   598      {
   599          mOperationTask.Post();
   600      }
   601  }
