   608  void Mac::PerformNextOperation(void)
   609  {
   610      VerifyOrExit(mOperation == kOperationIdle);
   611
   612      if (!mEnabled)
   613      {
   614          mPendingWaitingForData   = false;
   615          mPendingTransmitOobFrame = false;
   616          mPendingActiveScan       = false;
   617          mPendingEnergyScan       = false;
   618          mPendingTransmitBeacon   = false;
   619          mPendingTransmitData     = false;
   620          mTimer.Stop();
   650      // initialize MAC header
   651      fcf = Mac::Frame::kFcfFrameMacCmd | Mac::Frame::kFcfPanidCompression | Mac::Frame::kFcfFrameVersion2006;
   652
   653      if (mMacSource.IsShort())
   654      {
   655          fcf |= Mac::Frame::kFcfDstAddrShort | Mac::Frame::kFcfSrcAddrShort;
   656      }
   657      else
   658      {
   659          fcf |= Mac::Frame::kFcfDstAddrExt | Mac::Frame::kFcfSrcAddrExt;
   660      }
   661
   662      fcf |= Mac::Frame::kFcfAckRequest | Mac::Frame::kFcfSecurityEnabled;
   663
   664      aFrame.InitMacHeader(fcf, Mac::Frame::kKeyIdMode1 | Mac::Frame::kSecEncMic32);
   665      aFrame.SetDstPanId(netif.GetMac().GetPanId());
   666      aFrame.SetSrcAddr(mMacSource);
   667      aFrame.SetDstAddr(mMacDest);
   668      aFrame.SetCommandId(Mac::Frame::kMacCmdDataRequest);
   669
   670      mMessageNextOffset = aMessage.GetLength();
   671  }
